from pptx import Presentation
from pptx.util import Inches, Pt

def inspect_pptx(file_path):
    prs = Presentation(file_path)
    for i, slide in enumerate(prs.slides):
        print(f"Slide {i+1}")
        for shape in slide.shapes:
            if not shape.has_text_frame:
                continue
            for paragraph in shape.text_frame.paragraphs:
                print(f"  Shape: {shape.name}, Text: {paragraph.text}, Left: {shape.left.inches}, Top: {shape.top.inches}, Width: {shape.width.inches}, Height: {shape.height.inches}")

if __name__ == "__main__":
    inspect_pptx("/root/Awesome-Agent-Papers.pptx")

