from pptx import Presentation

def verify_pptx(file_path):
    prs = Presentation(file_path)
    print(f"Total slides: {len(prs.slides)}")

    # Check last slide
    last_slide = prs.slides[-1]
    for shape in last_slide.shapes:
        if shape.has_text_frame:
            print(f"Last slide shape: {shape.name}, Text: {shape.text[:50]}...")

    # Check a modified slide (e.g., Slide 2)
    slide2 = prs.slides[1]
    for shape in slide2.shapes:
        if "textbox" in shape.name.lower() or "文本框" in shape.name.lower():
            if shape.has_text_frame:
                p = shape.text_frame.paragraphs[0]
                run = p.runs[0]
                print(f"Slide 2 dangling title font: {run.font.name}, size: {run.font.size.pt}, color: {run.font.color.rgb}, bold: {run.font.bold}")
                print(f"Position: Left={shape.left.inches}, Top={shape.top.inches}, Width={shape.width.inches}")

if __name__ == "__main__":
    verify_pptx("/root/Awesome-Agent-Papers_processed.pptx")

